-- The model workbook's lookup sheets as Fabric SQL tables (database "gitsit-test"). Generated by
-- packages/frontend/scripts/gen-lookups.ts. Safe to rerun: each table is only created when missing.
-- The app fills empty tables from the workbook, then reads the BPL rows each time it opens and
-- writes them into the model before calculating, so a value changed here changes the results.

IF OBJECT_ID('dbo.EXIT') IS NULL
CREATE TABLE dbo.[EXIT] (
  [Table_Type] NVARCHAR(50) NOT NULL DEFAULT N'BPL',
  [Basis] NVARCHAR(400) NULL,
  [Segment] NVARCHAR(200) NOT NULL,
  [Outcome] NVARCHAR(200) NOT NULL,
  [LTV_Band] NVARCHAR(200) NOT NULL,
  [LTV_From] FLOAT NULL,
  [DQ_CUR] FLOAT NULL,
  [DQ_D30] FLOAT NULL,
  [DQ_D60] FLOAT NULL,
  [DQ_D90] FLOAT NULL,
  [DQ_4_6] FLOAT NULL,
  [DQ_7_9] FLOAT NULL,
  [DQ_10_12] FLOAT NULL,
  [DQ_13_15] FLOAT NULL,
  [DQ_16_18] FLOAT NULL,
  [DQ_19_24] FLOAT NULL,
  [DQ_25_36] FLOAT NULL,
  [DQ_37_48] FLOAT NULL,
  [DQ_49_60] FLOAT NULL,
  [DQ_61_Plus] FLOAT NULL,
  CONSTRAINT PK_EXIT PRIMARY KEY ([Table_Type], [Segment], [Outcome], [LTV_Band])
);
GO

